add('X05',1,'概念迁移成为双向部分透镜','A','language,subject','OntologyLens=(get,put,domain,unknown_policy,version_pair)，明确何时可往返、何时损失。','旧新本体只能用 ID 重命名衔接','定义旧到新解释 get|为可更新的公共字段定义部分 put|在指定域检查 get-put 与 put-get 条件|不满足条件的分裂保留集合映射或 unknown','存在可计算公共字段|往返律只在显式域成立','不得从旧粗概念猜测新细类别。','旧“钥匙有效”没有期限信息，不能唯一映到“临时/永久”；部分透镜暴露缺失。','双向变换已有完整文献需后续核查，候选贡献在认知协议生命周期结合。','N12,N06,S09')
add('X05',2,'有语义承诺的新基底原语','A,B','language,learning','PrimitiveProposal=(denotation,effect_type,authority,implementation_relation)，区别可展开宏和真正新测量/计算能力。','新指令只能是旧程序宏的简称','先判断候选是否有旧 ISA lowering|有 lowering 时只声明描述/搜索复杂度改进|无 lowering 时给独立数学语义、效果类型和后端能力证明义务|新权限或外部效果保持未绑定直到单独授权','新语义可独立定义|宿主能检查效果范围','语言演化永不自行升级控制面权限。','把 shell 调用包装成新 opcode 不构成合法能力增长；纯 add/multiply 宏也不增加可计算函数族。','不可约新原语可能需要新传感器/后端，尚未实现；不是因宏命名而产生超计算。','S09,N12,N04')
add('X05',3,'问题语言共同扩张的元语法生态','A,C','language,learning,world','MetaGrammarPopulation=(task_grammars,ontology_grammars,compiler_migrations,archive)，变异作用于生成规则而非只有参数。','任务和语言的生成语法固定不变','让已有概念缺口产生受限语法扩张候选|生成跨版本任务与编译器迁移义务|按可表达操作及独立结构描述归档多个生态位|回放旧公共任务关系以记录而非隐藏遗忘','元语法自身有类型和终止界|旧任务具有可回放关系','不以新概念数量或短期总分奖励无限造词。','只把 threshold 从 1 改 2 不是新语法；新增量词/关系算子才改变可表达操作且需新语义。','扩张能否持续产生有用而非作弊任务未证明，保留多分支而不承诺无界进步。','S09,S18,S19')
add('X06',1,'携带记忆核的非闭合宏语义','SCALE,B','time,learning','MemoryKernelState=(coarse_history,unresolved_initial,memory_operators)，把丢失细节的延迟效应纳入宏对象。','粗状态必须是一阶 Markov 且无需历史','给 C 和右逆 L 定义 d=x−LCx|推导粗态与残差联立递推|消去残差得到有限记忆核与初始项|截断时记录尾项界或保留未决误差','线性或可分析动力学|CL=I|截断界有明确条件','记忆项不能假称不存在或由零填充消除。','同总和的 (1,0),(0,1) 下一步粗态不同；历史/残差可修复但单一总和不行。','真实语义中的低复杂度记忆核是否存在未定。','N03,S14,N09')
add('X06',2,'以纤维分布而非代表元细化','SCALE,C','world,language','FiberBelief(m)=distribution over C^-1(m)，压缩对象携带可识别的不确定性。','一个粗态必须对应一个猜定微态','构造粗化纤维及条件分布族|用新查询条件化纤维分布|若无先验保留候选集合而非伪后验|把预测不确定性传播到宏动力学','条件分布来源可解释或保留集合|观察模型显式','不把重新采样的微态称恢复原微态。','奇数粗态可由 1 或 3 产生；抽中 1 不证明原数就是 1。','可计算的纤维分布可能过大，有限近似及误差需另定义，不以资源困难删除构想。','N03,S14,N05')
add('X06',3,'随查询演化的尺度选择器','SCALE,A','language,learning','ScalePolicy=(query_set,partition_refinement,closure_obligations)，新问题触发新尺度而非固定层级。','所有任务共用永久不变的语义粒度','从当前 query 签名建商结构|发现新增查询切开旧等价类|检验细化后动态闭合并生成迁移关系|没有原始信息时发出信息需求而非编造细节','可读取保留源信息或获得新观测|任务变化有明确授权','新增问题只细化既有精确分区，不静默合并。','奇偶后加入大于 2 得四类；若存储只有奇偶则必须请求来源。','如何选择最有用查询和尺度是未证 H，不等同信息瓶颈方法已解决。','S14,N03,S20')
add('X07',1,'偏序轨迹而非线性轮次','TRAJECTORY','time,subject','EventTrace=(events,happens_before,read_write_effects,commutation_witnesses)，只对独立操作交换次序。','所有计算都必须有唯一全局 token 顺序','构造事件依赖 DAG|对无冲突且作用可交换事件定义等价重排|把轨迹读出定义在等价类上|遇到数据依赖或非交换时保留顺序见证','事件效果可明示|交换性在声明域成立','并发不绕过读版本或作用域检查。','加一和乘二不交换，两个不同变量的独立加一可交换；只按无写冲突仍可能漏读依赖。','需要与并发迹理论完整比较；当前异步时钟并非已实现此语义商。','N01,N12,N10')
add('X07',2,'相位关系承载可恢复计算状态','TRAJECTORY','time,learning','PhaseRelationState=(torus_coordinates,relative_phase,window_readout,noise_contract)，状态在循环相位关系而非终点。','有意义计算必须收敛到固定点','规定耦合振子与允许读出|将共同相位平移取商而保留相对相位|用事件触发调整耦合并记录轨迹段|检查扰动和步长伪迹，保留不收敛但可区分读出','稳定相位关系可定义|读出区分与任务有可验证联系','不把振荡本身当智能或意识证据。','两个循环终点同但相位延迟不同；终点读取丢信息，窗口读出可区别。','相位编码是否能在真实模型间提供有用计算完全未验证。','S10,N10')
add('X07',3,'公开终端条件下的路径分布推理','TRAJECTORY,C','time,world','PathMeasure=(transition_factors,public_boundary,normalizer,branch_weights)，从单条最优路径扩成条件轨迹集合。','推理只能前向生成唯一答案轨迹','给有限转移概率和公开终端事件|计算前向和后向消息与归一常数|保留多条后验路径而非立即坍缩|零归一常数时返回边界不相容','核和边界来源合法|状态包含足够历史满足 Markov 分解','后向约束不获得未观测未来信息。','0 到 2 三步允许停留，有多条可行轨迹；把第一条当唯一解会丢不确定性。','双向消息已有，候选 H 在跨模型路径协议和读出，不是逆因果。','N13,N12,N09')
add('X08',1,'剩余证明义务的可迁移切片','A','time,subject','ProofContinuation=(proved_lemmas,open_goals,context,proof_kernel_version)，不是最后一段解释文本。','中途推理只能保存摘要或 KV','把已证与猜测分别注册|按依赖切片提取最小可接续上下文|目标端用同一或有验证翻译的证明内核接管|只消解实际完成义务并保留未解分支','有受限可检查证明演算|上下文和内核版本可迁移','猜测不升级为已证，目标不被替换。','摘要写“显然成立”却无引理依赖，不能算续接了证明。','自然语言研究中的未完成发现如何形式化仍为 H，不要求所有探索先形式化才允许存在。','N12,S03,N06')
add('X08',2,'带前提的整簇排除证书','A,B','time,learning','NoGoodRegion=(predicate,assumptions,certificate,domain_version)，迁移整个失败区域而非单一坏答案。','历史失败只能记为失败样本','把失败推导压成可检查排除条件|目标端证明当前任务蕴含 required constraint|在许可域剪枝并记录受影响分支|前提撤回后从原候选域恢复','证书覆盖被剪区域|必要条件关系可检查','timeout 或置信评分不成为硬排除。','排除所有奇数只在偶数约束有效；撤回约束必须恢复奇数。','模型能否提出广泛但正确区域证书未验证。','N06,N14,N12')
add('X08',3,'可并存的猜想修订谱系','A','time,language','ConjectureLineage=(claim_versions,refutations,repair_transformations,open_bridges)，保留相互竞争的修订而不单线覆盖。','反例到来后只能抹掉旧猜想或选唯一新猜想','保存原猜想精确作用域|生成加强、弱化、分域与新增变量的不同修订|逐条标明对旧问题的关系|允许多个后继继续生成义务，来源撤回时重算','修订关系可表达|未决桥梁可版本化追踪','不把修订后的正确命题归功于原错误命题。','“偶数都被4整除”可弱化域、反转蕴含或增加变量，三者不是同一个修复。','怎样选择有研究生产力的谱系未定，不能以多数票定理论真伪。','N06,N14,S09')
add('X09',1,'因果机制接枝形成新世界','C','world,subject','GraftWorld=(local_SCMs,boundary_units,shared_noise,intervention_map)，多个源各持部分方程。','一个世界必须由单个完整生成器先存在','定义各模块父边界和单位|检查联合 DAG 与共享噪声身份|拼合并仅重算受影响后代|给每项可干预结论保留模块来源','模块方程可执行且边界正确|联合噪声给定','合成世界不继承现实真实性标签。','独立抽两份天气噪声改变两个传感器联合行为，即使边缘不变。','自然模型中识别模块是强假设，有限 SCM 接枝不证明已找到它。','S12,S13,N09')
add('X09',2,'世界规律的对抗边界生成器','C,A','world,learning','CounterfactualBoundarySearch=(kernel_edit_grammar,distinguishing_queries,validity_constraints)，搜索改变哪条机制才改变结论。','想象只用于生成更多同分布样本','枚举受限机制编辑而非表面文本变化|保持类型与归一性，更新 world_id|寻找两个世界在允许查询上的最小区分见证|把新问题及编辑谱系返回给概念/规则系统','允许比较的机制编辑有清晰语义|查询不能泄露生成答案','自造反例只反驳合成世界内主张，不直接推翻现实事实。','将门从单向改双向改变可达性；仅给节点重命名不产生新的规律。','生成差异不等于科学重要性，价值判断仍是明确 H。','S18,S19,S20')
add('X09',3,'联合噪声不确定性的世界集合','C,NON_GLOBAL','world,language','CouplingSet={joint laws with declared marginals and dependence constraints}，消息携带一族世界而非猜定独立联合。','给出局部核边缘即可唯一合成世界','登记边缘与已知相关约束|构造可行 coupling 集|对问题求上下界或找到相反结论的两种 coupling|选择能缩小 coupling 集的许可查询','有限约束可表示|边缘本身可靠或另带误差区间','依赖未知时不返回伪精确概率。','两公平比特可相同、相反或独立，P(相等) 可为1、0、.5。','真实联合依赖能否被低复杂度表示未定；不是靠多模型数量保证识别。','S13,N13,S20')
add('X10',1,'能力超边而非单体排名','B','subject,learning','CapabilityHypergraph=(input_types,provider_sets,output_types,composition_witness)，能力属于有条件联盟。','联合能力必能由单体分数相加得到','登记每个组件所需与所产类型|枚举满足共同输入的超边|按真实联合任务关系构造价值表，未知留空|保留互补但单体低分的联盟','有明确组合操作|联合价值定义不混淆额外资源','内部信用不是金钱，不能执行对外交易。','两人各只有一个 XOR 比特，单源对 XOR 无信息、联合有信息；不等于所有 PID 定义一致。','联合能力是否能由不同模型实现尚未验证。','N02,S17')
add('X10',2,'来源商下的贡献分摊','B,NON_GLOBAL','subject,language','ProvenanceCoalitionGame 将玩家持有的支持 DAG 映到唯一来源/操作贡献，再定义 v(S)。','更多转述者就是更多独立贡献','规范化共享来源原子|区分信息支持与操作执行价值|对完整子集价值计算 Shapley 或标有界估计|撤回来源后使相关分摊待重算','来源身份至少局部可追溯|选择的价值函数符合用途','重复 .8 来源仍是一个事件，非 .96。','复制同一来源100次不应增加信息支持，但维护成本可以另计而不能混成真实性。','预训练相关性不可完全追踪，来源商只能局部成立。','S21,N06,S17')
add('X10',3,'带退出义务的临时计算联盟','B','subject,time','JoinLeaveContract=(required_state,obligation_transfer,tombstones,exit_conditions)，联盟动态变化时保留计算责任。','成员退出仅删除名字不影响程序语义','入盟时检查能力、输入与共享预算|运行中为未完成义务指定接收者|退出前迁移必要状态或显式中止依赖分支|版本冲突时保留旧联盟快照而非半迁移','义务可转移或可中止|状态迁移在声明合同内可靠','不能让成员退出抹掉来源与责任，不能强迫未授权后端加入。','持唯一中间变量的成员退出后其余仍报告完成，是义务丢失反例。','动态联盟的活性与容错超出现有本地事务保证，需独立设计。','N01,N12,N04')
add('X11',1,'分岔触发而非手工命名的概念分裂','A,BIFURCATION','language,learning','StructuralBifurcation=(control_parameter,order_observable,branch_atlas,migration)，将结构变量与连续态分开。','概念数只能靠预先固定模板指定','定义控制参数及状态动力学|查找稳定解结构变化并排除积分器伪迹|为不同分支构造新的可计算谓词|把新旧概念关系作版本迁移，而非改写历史标签','分支对任务可观察作用不同|分岔与离散类型变化有明确映射','性能跳点不是热力学相变证据。','alpha=0 的导数为0仍可渐近稳定；粗步长产生发散不代表概念诞生。','数学分岔如何驱动真实认知类型变化尚未证明。','S10,N10,S09')
add('X11',2,'可复活的概念墓志与适用域','A','language,time','RetiredConcept=(historical_reader,expiry_conditions,reactivation_conditions,evidence_lineage)，退休不是删除定义。','概念失效后只能彻底删除或永久保留为真','声明失效范围与依赖原因|把当前 reader 切到替代概念|保留历史 reader 和迁移失败值|新证据满足复活条件时创建新版本，不复写旧记录','适用域和证据变化可记录|历史解释仍有合法用途','退休不等于模型参数遗忘，也不隐藏旧错误。','旧授权期限缺失时不能用新概念重算出确定历史有效性。','自然任务概念生命周期可能无法清晰离散，需部分/不确定版本。','N06,S21,N12')
add('X11',3,'多本体分支的事务性合并','A,NON_GLOBAL','language,subject,time','OntologyMerge=(base,left,right,semantic_conflicts,migration_proofs)，三方合并对象包含定义关系而非文本 diff。','两个概念改动文件不冲突即语义可合并','从共同旧快照读取两个本体分支|比较类型、谓词外延和消费者影响|对可兼容部分建立迁移，对冲突部分保留双版本|在同一提交检查所有读版本后发布','语义冲突能在声明有限域检测|迁移顺序与依赖明确','语法合并成功不冒充语义一致。','一支把“有效”限为临时，另一支把它扩成永久；文本不同字段也可能影响同一消费者。','全域语义合并一般不可判，有限证据之外须保留桥梁而非强行全局统一。','N01,N06,S09')
add('X12',1,'证明携带的语义 lowering','A,SCALE','language,learning','ProofCarryingIR=(typed_ops,domain,lowering_relation,error_budget)，每个 pass 输出作用关系证书。','编译通过只意味着形状合法','对每个操作给解释函数和效果类型|转换 pass 同时生成局部交换关系|按路径组合证明或误差界|后端不满足能力时返回 unbound','有限语义可验证或规则有证明|误差界适用域闭合','类型正确不自动语义正确，也不授予运行权限。','add 后 multiply 被改成 multiply 后 add，形状一致但 x=0 输出不同。','神经后端的操作关系需另建证据，静态 IR 不能认证其能力。','N12,S09,S13')
add('X12',2,'带局部图册的多后端编译','B,SCALE','subject,language','BackendAtlas=(local_domains,frame_maps,operator_contracts,path_residuals)，同一语义程序在不同域绑定不同后端。','存在一套全局共享向量坐标即可编译所有任务','按操作域划分图册|为每条跨端边给坐标运输和行为锚|编译时选择满足域与能力的路径|路径不一致时保留候选及残差而非隐藏成同一个结果','局部操作可对应|转换误差和条件数有范围','异维压缩不进入可逆换基分支。','两个局部映射分别好但跨出覆盖域，复合可能失效；不能只验单边锚。','未知任务是否有合适图册未证明，路径相关性不自动是语义曲率。','S06,S02,S12')
add('X12',3,'任务尺度共同决定的分层编译','C,SCALE','world,language,time','ScaleAwareProgram=(query_contract,macro_ops,memory_residuals,refinement_requests)，按任务选择粗细操作及信息保留。','固定层级网络就是所有问题的最佳执行尺度','从问题需要的观测定义粗化候选|检查宏操作闭合或生成记忆状态|在必要分支请求细节并保留回译|把精度损失与执行路径显式交给后续义务','粗化保指定任务|细节请求可由源信息支持','宏程序不能生成被压缩丢失的事实。','只有奇偶的缓存无法回答是否大于2，编译器必须请求细化而非选择一个代表元回答。','如何自动发现高效尺度尚为 H；标准聚合与细化不声称新创。','N03,S14,N05,N12')


add('X11',4,'由 Hopf 环上的相位关系定义动态概念','A,TRAJECTORY,BIFURCATION','language,time','PhaseConceptAtlas=(amplitude,relative_phase,periodic_readout,phase_invariant_contract)，概念驻留于稳定周期轨道及相位关系而非单个固定点。','所有可保持的概念必须对应静止吸引点','给二维 Hopf 正规形及控制参数明确定义|用径向方程证明周期轨道存在与局部吸引，而非只看离散回返|把共同时移视为同一相位参考变换，读出相对相位|将相位丢失或振幅穿零记录为概念失效/重新绑定事件','频率非零|局部动力学近似满足正规形条件|任务读出对相对相位有明确意义','纯旋转、中性周期与吸引极限环分开，不把积分器振荡当概念。','mu>0 的 rdot=mu r-r³ 有吸引半径 sqrt(mu)；删去径向耗散项的纯 skew 旋转并没有吸引半径，二者不能混为周期记忆。','Hopf 定理和振荡编码均有既有文献需专门核查；周期轨道能否成为跨模型概念接口仍是 V。','S10,N10,S06')
add('X11',5,'折叠分岔与迟滞的历史依赖概念','A,BIFURCATION','language,time','HystereticConcept=(control,stable_branch,history,fold_conditions)，同一当前控制值可以因历史位于不同稳定解释分支。','当前输入及一个固定词典足以唯一决定概念状态','以 xdot=mu+x-x³ 定义可分析的分支图|在 x=±1/sqrt(3) 找折叠并标注外支稳定/内支不稳定|用缓慢升降控制形成不同分支继承路径，明确绝热条件和失稳延迟|将分支历史写入消息，必要时对两个合法解释并行推理','读出区分稳定分支|变化足够慢才可近似准静态迟滞|有噪声时需另给跃迁语义','历史依赖不是任意改目标，外部事实与权限不随分支改变。','mu=0 时 x=±1 均稳定而 x=0 不稳定；只传 mu 不传分支无法唯一恢复状态。','标准灾变/迟滞理论不主张原创，真实认知语义的状态变量和控制参量尚未识别。','S10,N06,N10')

